PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        source_id TEXT UNIQUE,
        handle TEXT,
        title TEXT NOT NULL,
        description TEXT,
        price_pkr REAL,
        compare_at_pkr REAL,
        available INTEGER DEFAULT 0,
        image_url TEXT,
        source_url TEXT,
        category TEXT,
        sourcing_enabled INTEGER DEFAULT 1,
        priority TEXT DEFAULT 'normal',
        min_margin_pct REAL DEFAULT 20,
        condition_rule TEXT DEFAULT 'used,refurbished,new',
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
      );
CREATE TABLE zones (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        country TEXT NOT NULL,
        city TEXT,
        radius_km REAL,
        enabled INTEGER DEFAULT 0,
        operator TEXT,
        notes TEXT
      );
CREATE TABLE sellers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        platform TEXT,
        contact TEXT,
        country TEXT,
        city TEXT,
        lat REAL,
        lng REAL,
        reliability REAL,
        notes TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
      , location_text TEXT, seller_type TEXT DEFAULT 'seller', status TEXT DEFAULT 'active', reliability_score REAL DEFAULT 0, response_speed TEXT, updated_at TEXT);
CREATE TABLE opportunities (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        product_id INTEGER,
        seller_id INTEGER,
        source TEXT,
        listing_url TEXT,
        asking_price REAL,
        currency TEXT DEFAULT 'THB',
        quantity INTEGER DEFAULT 1,
        distance_km REAL,
        travel_mode TEXT,
        travel_cost_pkr REAL DEFAULT 0,
        pickup_cost_pkr REAL DEFAULT 0,
        landed_cost_pkr REAL DEFAULT 0,
        expected_margin_pct REAL,
        status TEXT DEFAULT 'found',
        notes TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
      , zone_id INTEGER, condition TEXT DEFAULT 'used', target_price REAL, max_buy_price REAL, packing_cost REAL DEFAULT 0, freight_cost REAL DEFAULT 0, duties_cost REAL DEFAULT 0, payment_fee REAL DEFAULT 0, pakistan_transport_cost REAL DEFAULT 0, contingency_cost REAL DEFAULT 0, retail_price_pkr REAL DEFAULT 0, target_margin_pct REAL DEFAULT 20, expected_profit REAL DEFAULT 0, approval_status TEXT DEFAULT 'pending', travel_cost REAL DEFAULT 0, pickup_cost REAL DEFAULT 0, landed_cost REAL DEFAULT 0);
CREATE TABLE settings (
        key TEXT PRIMARY KEY,
        value TEXT
      );
CREATE TABLE seller_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      seller_id INTEGER NOT NULL,
      product_id INTEGER,
      deal_date TEXT,
      quantity INTEGER DEFAULT 1,
      asking_price REAL,
      agreed_price REAL,
      currency TEXT DEFAULT 'PKR',
      outcome TEXT,
      notes TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE market_sources (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, website TEXT, country TEXT, city TEXT, source_type TEXT DEFAULT 'online_retail', enabled INTEGER DEFAULT 1, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_market_prices (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, source_id INTEGER NOT NULL, source_product_url TEXT, currency TEXT DEFAULT 'THB', price REAL, price_pkr REAL, availability TEXT, captured_at TEXT DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE TABLE supplier_offers (id INTEGER PRIMARY KEY AUTOINCREMENT, seller_id INTEGER, product_id INTEGER NOT NULL, online_reference_price REAL, dealer_price REAL, negotiated_price REAL, currency TEXT DEFAULT 'THB', min_quantity INTEGER DEFAULT 1, warranty TEXT, quote_date TEXT, status TEXT DEFAULT 'reference', notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE logistics_rates (id INTEGER PRIMARY KEY AUTOINCREMENT, origin_country TEXT, origin_city TEXT, destination_country TEXT, destination_city TEXT, transport_mode TEXT, charge_type TEXT, rate REAL, currency TEXT DEFAULT 'PKR', min_charge REAL DEFAULT 0, source_url TEXT, rate_type TEXT DEFAULT 'estimate', valid_from TEXT, valid_until TEXT, status TEXT DEFAULT 'active', notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fx_rates (id INTEGER PRIMARY KEY AUTOINCREMENT, base_currency TEXT NOT NULL, quote_currency TEXT NOT NULL, rate REAL NOT NULL, source TEXT, rate_date TEXT, fetched_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(base_currency,quote_currency,rate_date));
CREATE TABLE freight_quotes (id INTEGER PRIMARY KEY AUTOINCREMENT, origin_country TEXT, origin_city TEXT, destination_country TEXT, destination_city TEXT, mode TEXT, weight_kg REAL, volume_cbm REAL, amount REAL, currency TEXT, source TEXT, source_url TEXT, valid_until TEXT, fetched_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customs_rates (id INTEGER PRIMARY KEY AUTOINCREMENT, hs_code TEXT, pct_code TEXT, description TEXT, customs_duty_pct REAL, source TEXT, source_url TEXT, tariff_year TEXT, verified_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE market_quotes (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER, seller_id INTEGER, source TEXT, source_url TEXT, price REAL, currency TEXT, quantity INTEGER DEFAULT 1, condition TEXT, quote_date TEXT, verified_at TEXT DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE TABLE buyers (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT,whatsapp TEXT,email TEXT,city TEXT DEFAULT 'Pakistan',country TEXT DEFAULT 'Pakistan',company TEXT,status TEXT DEFAULT 'active',notes TEXT,created_at TEXT,updated_at TEXT, country_code TEXT DEFAULT '');
CREATE TABLE buyer_requirements (id INTEGER PRIMARY KEY AUTOINCREMENT,buyer_id INTEGER NOT NULL,product_keyword TEXT,quantity INTEGER DEFAULT 1,max_budget_pkr REAL DEFAULT 0,target_price_pkr REAL DEFAULT 0,notes TEXT,status TEXT DEFAULT 'active',created_at TEXT,updated_at TEXT);
CREATE TABLE buyer_matches (id INTEGER PRIMARY KEY AUTOINCREMENT,buyer_id INTEGER NOT NULL,requirement_id INTEGER NOT NULL,product_id INTEGER NOT NULL,seller_id INTEGER,match_status TEXT DEFAULT 'matched',notes TEXT,created_at TEXT,updated_at TEXT);
CREATE TABLE seller_offers (id INTEGER PRIMARY KEY AUTOINCREMENT, seller_id INTEGER NOT NULL, product_id INTEGER NOT NULL, asking_price REAL NOT NULL DEFAULT 0, currency TEXT DEFAULT 'THB', quantity INTEGER DEFAULT 1, distance_km REAL DEFAULT 0, travel_mode TEXT, listing_url TEXT, source TEXT, status TEXT DEFAULT 'active', notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, buyer_id INTEGER, requirement_id INTEGER, product_id INTEGER, product_title TEXT, customer_name TEXT NOT NULL, phone TEXT, whatsapp TEXT, email TEXT, city TEXT, delivery_address TEXT, quantity INTEGER NOT NULL DEFAULT 1, requested_price_pkr REAL, max_budget_pkr REAL, request_type TEXT DEFAULT 'order_request', customer_note TEXT, status TEXT DEFAULT 'new', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, country_code TEXT DEFAULT '', assigned_partner_id INTEGER, assigned_partner_name TEXT DEFAULT '', idempotency_key TEXT);
CREATE TABLE owner_approvals (id INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id INTEGER NOT NULL, decision TEXT NOT NULL, approved_by TEXT DEFAULT 'Owner', note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE quotations (id INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id INTEGER, buyer_id INTEGER, product_id INTEGER, quote_number TEXT UNIQUE NOT NULL, customer_name TEXT, customer_phone TEXT, customer_whatsapp TEXT, quantity INTEGER DEFAULT 1, unit_price_pkr REAL DEFAULT 0, total_price_pkr REAL DEFAULT 0, valid_until TEXT, status TEXT DEFAULT 'draft', notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, quotation_id INTEGER, opportunity_id INTEGER, buyer_id INTEGER, order_number TEXT UNIQUE NOT NULL, product_id INTEGER, quantity INTEGER DEFAULT 1, sale_unit_price_pkr REAL DEFAULT 0, sale_total_pkr REAL DEFAULT 0, status TEXT DEFAULT 'new', payment_status TEXT DEFAULT 'pending', customer_note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE purchase_tracking (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, opportunity_id INTEGER, seller_id INTEGER, purchase_status TEXT DEFAULT 'pending', agreed_price_pkr REAL DEFAULT 0, currency TEXT DEFAULT 'PKR', quantity INTEGER DEFAULT 1, purchase_date TEXT, tracking_ref TEXT, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE delivery_tracking (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, delivery_status TEXT DEFAULT 'pending', carrier TEXT, tracking_number TEXT, origin TEXT, destination TEXT DEFAULT 'Faisalabad, Pakistan', estimated_date TEXT, delivered_date TEXT, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT DEFAULT 'internal', channel TEXT DEFAULT 'dashboard', recipient TEXT, subject TEXT, message TEXT, related_type TEXT, related_id INTEGER, status TEXT DEFAULT 'pending', sent_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE negotiations (id INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id INTEGER, buyer_match_id INTEGER, seller_id INTEGER NOT NULL, offer_id INTEGER, status TEXT DEFAULT 'active', attempt_count INTEGER DEFAULT 0, max_attempts INTEGER DEFAULT 3, last_contact_at TEXT, next_followup_at TEXT, original_price_pkr REAL DEFAULT 0, last_offer_price_pkr REAL DEFAULT 0, seller_counter_price_pkr REAL DEFAULT 0, agreed_price_pkr REAL DEFAULT 0, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sync_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sync_status TEXT DEFAULT 'success',
      products_count INTEGER DEFAULT 188,
      last_run TEXT DEFAULT CURRENT_TIMESTAMP,
      notes TEXT
    );
CREATE TABLE store_inventory (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      item_name TEXT NOT NULL,
      stock_status TEXT DEFAULT 'In Stock',
      threshold INTEGER DEFAULT 5,
      current_qty INTEGER DEFAULT 10
    );
CREATE TABLE gmail_oauth (id INTEGER PRIMARY KEY CHECK(id=1), refresh_token TEXT, updated_at TEXT);
CREATE TABLE gmail_oauth_state (state TEXT PRIMARY KEY, expires_at INTEGER, owner_session_nonce TEXT);
CREATE TABLE customer_approvals (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_request_id INTEGER NOT NULL, decision TEXT NOT NULL, approved_by TEXT DEFAULT 'Owner', note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
