INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(3241,'9046777233461','msi-geforce-rtx-2080-ventus-8g-8gb-gddr6-graphics-card','MSI GeForce RTX 2080 VENTUS 8G 8GB GDDR6 Graphics Card in Pakistan',replace('<p><strong>Buy MSI GeForce RTX 2080 VENTUS 8G 8GB GDDR6 Graphics Card in Pakistan from SakoonSay Gaming Store.</strong> Powered by NVIDIA Turing architecture, the RTX 2080 delivers excellent performance for high-FPS gaming, 1440p gaming, ray tracing, streaming, video editing, and other GPU-intensive workloads.</p>\n<p>The MSI VENTUS dual-fan cooling system provides efficient thermal performance, while its <strong>8GB GDDR6 256-bit memory</strong> provides the bandwidth needed for demanding games and creative applications.</p>\n<h2>MSI RTX 2080 VENTUS 8G Specifications</h2>\n<ul>\n<li>NVIDIA GeForce RTX 2080 GPU</li>\n<li>8GB GDDR6 VRAM</li>\n<li>256-bit memory interface</li>\n<li>2944 CUDA cores</li>\n<li>Up to 1710 MHz boost clock</li>\n<li>14 Gbps memory speed</li>\n<li>PCI Express 3.0 x16</li>\n<li>Dual-fan MSI VENTUS cooling</li>\n<li>Ray Tracing and NVIDIA DLSS support</li>\n<li>3 × DisplayPort</li>\n<li>1 × HDMI</li>\n<li>1 × USB Type-C</li>\n<li>1 × 8-pin + 1 × 6-pin power connectors</li>\n<li>Recommended PSU: 650W</li>\n<li>Maximum digital resolution: 7680 × 4320</li>\n</ul>\n<h2>Why Buy From SakoonSay Gaming Store?</h2>\n<p>Free delivery across Pakistan with payment options including COD, bank transfer, Easypaisa and JazzCash. Used products include a <strong>15-day checking warranty</strong>.</p>\n<p><strong>Order MSI RTX 2080 VENTUS 8GB online in Pakistan from SakoonSay Gaming Store, Faisalabad.</strong></p>','\n',char(10)),70000,NULL,1,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/msi-rtx-2080-ventus-8g-angle.png?v=1789903471','https://sakoonsay.com/products/msi-geforc