INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(3242,'9046525870133','intel-core-i5-8600k-8th-gen-6-core-lga1151-processor-used','Intel Core i5-8600K 8th Gen 6-Core LGA1151 Processor – Used',replace('<h2>Intel Core i5-8600K 8th Gen Processor – Used</h2>\n<p>The <strong>Intel Core i5-8600K</strong> is an unlocked 8th Generation Coffee Lake desktop processor with 6 physical cores, designed for gaming and everyday high-performance desktop PCs.</p>\n<p><strong>Condition:</strong> Used / system pulled. <strong>CPU only</strong>; retail box and cooler are not included.</p>\n<h3>Key Specifications</h3>\n<ul>\n<li>\n<strong>Generation:</strong> 8th Gen Intel Core</li>\n<li>\n<strong>Architecture:</strong> Coffee Lake</li>\n<li>\n<strong>Cores:</strong> 6</li>\n<li>\n<strong>Threads:</strong> 6</li>\n<li>\n<strong>Base Frequency:</strong> 3.60 GHz</li>\n<li>\n<strong>Max Turbo Frequency:</strong> Up to 4.30 GHz</li>\n<li>\n<strong>Cache:</strong> 9MB Intel Smart Cache</li>\n<li>\n<strong>Socket:</strong> LGA1151</li>\n<li>\n<strong>TDP:</strong> 95W</li>\n<li>\n<strong>Memory Support:</strong> DDR4-2666</li>\n<li>\n<strong>Integrated Graphics:</strong> Intel UHD Graphics 630</li>\n<li>\n<strong>Unlocked Multiplier:</strong> Yes</li>\n<li>\n<strong>PCI Express:</strong> PCIe 3.0</li>\n<li>\n<strong>Condition:</strong> Used</li>\n<li>\n<strong>Packaging:</strong> CPU only / without retail box</li>\n</ul>\n<p>Compatible with supported Intel 300-series LGA1151 motherboards. For overclocking, a compatible Z-series motherboard and suitable CPU cooling are recommended.</p>\n<p>Available from <strong>SakoonSay Gaming Store</strong>, Faisalabad, with delivery across Pakistan.</p>\n<p> </p>','\n',char(10)),17000,NULL,1,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/intel-core-i5-8600k-cpu-used.jpg?v