INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(3245,'9046524592181','amd-ryzen-5-7500f-6-core-12-thread-am5-zen-4-processor-tray','AMD Ryzen 5 7500F 6-Core 12-Thread AM5 Zen 4 Processor – Tray',replace('<h2>AMD Ryzen 5 7500F AM5 Zen 4 Tray Processor</h2><p>Build a powerful AM5 gaming PC with the <strong>AMD Ryzen 5 7500F</strong>. Based on AMD Zen 4 architecture, this 6-core, 12-thread processor delivers excellent gaming and multitasking performance with boost speeds up to 5.0GHz.</p><p><strong>Important:</strong> This is a <strong>tray processor / CPU only</strong>. Retail box is not included. A <strong>dedicated graphics card is required</strong> because the Ryzen 5 7500F does not include integrated graphics.</p><h3>Key Specifications</h3><ul>\n<li>\n<strong>Cores:</strong> 6</li>\n<li>\n<strong>Threads:</strong> 12</li>\n<li>\n<strong>Architecture:</strong> Zen 4 (Raphael)</li>\n<li>\n<strong>Base Clock:</strong> 3.7GHz</li>\n<li>\n<strong>Max Boost Clock:</strong> Up to 5.0GHz</li>\n<li>\n<strong>L3 Cache:</strong> 32MB</li>\n<li>\n<strong>Socket:</strong> AM5</li>\n<li>\n<strong>Memory:</strong> DDR5</li>\n<li>\n<strong>PCI Express:</strong> PCIe 5.0</li>\n<li>\n<strong>Default TDP:</strong> 65W</li>\n<li>\n<strong>Integrated Graphics:</strong> None – dedicated GPU required</li>\n<li>\n<strong>Packaging:</strong> Tray / without retail box</li>\n</ul><h3>Ideal For Gaming PCs</h3><p>The Ryzen 5 7500F is an excellent entry into the AM5 platform for gaming, streaming, multitasking and modern PC builds. Pair it with an AM5 motherboard, DDR5 memory and a dedicated graphics card.</p><p>Available from <strong>SakoonSay Gaming Store</strong> in Faisalabad with delivery across Pakistan.</p>','\n',char(10)),34000,NULL,1,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/amd-ryzen-5-7500f-t