INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(3417,'8208965304373','gigabyte-b460-aorus-pro-ac-b460-lga1200-gaming-motherboard','GIGABYTE B460 AORUS PRO AC B460 LGA1200 Gaming Motherboard',replace('<p>Build a powerful 10th Gen Intel gaming PC with the GIGABYTE B460 AORUS PRO AC. Featuring an 8+2 phase digital VRM, dual NVMe M.2 slots with Thermal Guards, built-in Wi-Fi, Bluetooth 5.0, Intel 2.5GbE LAN and advanced cooling, it delivers a strong foundation for gaming and performance-focused builds.</p>\n<p> </p>\n<p class="isSelectedEnd"><span>The </span><strong><span>GIGABYTE B460 AORUS PRO AC (Rev. 1.0)</span></strong><span> is a feature-packed ATX gaming motherboard designed for </span><strong><span>10th Generation Intel Core processors</span></strong><span> on the LGA1200 socket.</span></p>\n<p class="isSelectedEnd"><span>Its </span><strong><span>Direct 8+2 Phase Digital VRM</span></strong><span> and advanced thermal design help provide stable power delivery and cooling for demanding gaming workloads. Four DDR4 DIMM slots support up to </span><strong><span>128GB memory</span></strong><span>, giving builders plenty of capacity for gaming, multitasking and productivity.</span></p>\n<p class="isSelectedEnd"><span>For fast storage, the motherboard provides </span><strong><span>dual PCIe 3.0 x4 M.2 slots with Thermal Guards</span></strong><span>, helping you take advantage of high-speed NVMe SSDs while managing drive temperatures.</span></p>\n<p class="isSelectedEnd"><span>Connectivity is another major strength. Built-in </span><strong><span>Intel dual-band 802.11ac Wi-Fi</span></strong><span>, </span><strong><span>Bluetooth 5.0</span></strong><span> and </span><strong><span>Intel 2.5GbE LAN</span></strong><span> give gamers flexible high-speed networking options. USB 3.2 Gen 2 Type-C support adds convenient connectivity for modern peripherals.</span></p>\n<p class="isSelectedEnd"><span>Premium </span><strong><span>Realtek ALC1220-VB HD Audio</span></strong><span>, RGB Fusion 2.0, Smart Fan 5 and a pre-installed I/O shield round out a motherboard built for powerful, clean and feature-rich gaming systems.</span></p>\n<h3><span>Performance Highlights</span></h3>\n<p class="isSelectedEnd"><span>• Direct 8+2 Phase Digital VRM</span><br><span>• Advanced thermal design with enlarged heatsink</span><br><span>• Dual PCIe 3.0 x4 NVMe M.2 support</span><br><span>• M.2 Thermal Guards</span><br><span>• Intel 2.5GbE LAN</span><br><span>• Built-in dual-band Wi-Fi</span><br><span>• Bluetooth 5.0</span><br><span>• Smart Fan 5 cooling control</span><br><span>• USB 3.2 Gen 2 Type-C</span><br><span>• ALC1220-VB high-definition audio</span><br><span>• RGB Fusion 2.0</span><br><span>• Q-Flash Plus</span></p>\n<h2><span>Specifications</span></h2>\n<p><strong><span>Brand:</span></strong><span> GIGABYTE</span><br><strong><span>Model:</span></strong><span> B460 AORUS PRO AC (Rev. 1.0)</span><br><strong><span>Chipset:</span></strong><span> Intel B460 Express</span><br><strong><span>Socket:</span></strong><span> LGA1200</span><br><strong><span>CPU Support:</span></strong><span> 10th Gen Intel Core i9 / i7 / i5 / i3, Pentium &amp; Celeron</span><br><strong><span>Form Factor:</span></strong><span> ATX</span><br><strong><span>Memory:</span></strong><span> 4 × DDR4 DIMM</span><br><strong><span>Maximum Memory:</span></strong><span> Up to 128GB</span><br><strong><span>Memory Architecture:</span></strong><span> Dual Channel</span><br><strong><span>Storage:</span></strong><span> 2 × M.2 + 6 × SATA 6Gb/s</span><br><strong><span>Primary GPU Slot:</span></strong><span> PCIe 3.0 x16</span><br><strong><span>LAN:</span></strong><span> Intel 2.5GbE</span><br><strong><span>Wi-Fi:</span></strong><span> Intel 802.11ac Dual-Band</span><br><strong><span>Bluetooth:</span></strong><span> Bluetooth 5.0</span><br><strong><span>Audio:</span></strong><span> Realtek ALC1220-VB HD Audio</span><br><strong><span>Display Outputs:</span></strong><span> HDMI + DisplayPort</span><br><strong><span>USB Type-C:</span></strong><span> Yes, USB 3.2 Gen 2</span><br><strong><span>RGB:</span></strong><span> RGB Fusion 2.0</span><br><strong><span>BIOS Feature:</span></strong><span> Q-Flash Plus</span></p>','\n',char(10)),18000,NULL,0,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/25144.png?v=1786176727','https://sakoonsay.com/products/gigabyte-b460-aorus-pro-ac-b460-lga1200-gaming-motherboard.js','Intel Motherboard',1,'normal',20,'used,refurbished,new','2026-10-22 08:04:26');
