INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(3444,'7875163553845','6-7th-gen-motherboard-asus-q170m-c-micro-atx','ASUS Q170M-C LGA1151 Motherboard – 6th/7th Gen Micro-ATX',replace('<p>Build or upgrade a compatible Intel or AMD desktop PC with the <strong>ASUS Q170M-C LGA1151 motherboard</strong>. This listing is aimed at Pakistan buyers who need a clear platform match for their processor, DDR memory, graphics card and storage. Confirm the exact model and revision before ordering because motherboard features can vary by revision.</p>\n<h2>Specifications</h2>\n<table><tbody>\n<tr>\n<th>Chipset</th>\n<td>Intel Q170</td>\n</tr>\n<tr>\n<th>CPU socket</th>\n<td>LGA1151</td>\n</tr>\n<tr>\n<th>Memory</th>\n<td>DDR4; Model-dependent; dual-channel</td>\n</tr>\n<tr>\n<th>Form factor</th>\n<td>Micro-ATX</td>\n</tr>\n<tr>\n<th>Expansion and storage</th>\n<td>PCIe x16 graphics expansion and SATA storage</td>\n</tr>\n<tr>\n<th>Condition</th>\n<td>As listed; confirm exact stock condition</td>\n</tr>\n</tbody></table>\n<h2>Compatibility guidance</h2>\n<p>6th Gen Intel support; 7th Gen depends on exact model and BIOS. Do not choose a motherboard by socket name alone: chipset generation, board revision, BIOS version and memory type must also match. DDR3, DDR4 and DDR5 are not interchangeable. Check your case clearance, power connectors, RAM kit, M.2/SATA interface and graphics-card clearance before purchase.</p>\n<h2>Frequently asked questions</h2>\n<h3>Which processor works with this motherboard?</h3>\n<p>6th Gen Intel support; 7th Gen depends on exact model and BIOS. Check the manufacturer CPU support list and BIOS requirement for the exact revision.</p>\n<h3>Can I use DDR3 or DDR5 RAM?</h3>\n<p>No. Use only DDR4 memory supported by this board. Desktop RAM generations are not interchangeable.</p>\n<h3>Can I install a dedicated graphics card?</h3>\n<p>Yes, the listing includes PCIe graphics expansion. Confirm the slot, case clearance and power-supply requirements of your chosen GPU.</p>\n<h3>Will an M.2 SSD work?</h3>\n<p>PCIe x16 graphics expansion and SATA storage. Confirm whether your specific SSD is PCIe/NVMe or SATA and check the board''s manual before ordering.</p>\n<p>For help matching a processor, RAM kit or graphics card, contact SakoonSay Gaming Store in Faisalabad before purchase.</p>','\n',char(10)),8000,15000,1,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/q170-6th-gen-motherboard-asus-q170m-c-micro-atx.jpg?v=1742061428','https://sakoonsay.com/products/6-7th-gen-motherboard-asus-q170m-c-micro-atx.js','Intel Motherboard',1,'normal',20,'used,refurbished,new','2026-10-22 08:04:41');
