INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(3503,'7734082109493','gigabyte-graphic-card-gtx-1060-3gb-windforce-gddr5-without-box-used','Gigabyte Graphic Card GTX 1060 3GB Windforce GDDR5 Without Box Used',replace('<h2>Gigabyte GeForce GTX 1060 3GB WINDFORCE — Used, Without Box</h2><p>Gigabyte GeForce GTX 1060 3GB GDDR5 graphics card with WINDFORCE 2X dual-fan cooling. This listing is for a used card without its retail box. Price: Rs. 26,000 in Pakistan. Please confirm availability and physical condition before ordering.</p><h3>Specifications</h3><ul>\n<li>GPU: NVIDIA GeForce GTX 1060</li>\n<li>Graphics memory: 3GB GDDR5, 192-bit interface</li>\n<li>Cooling: Gigabyte WINDFORCE 2X with blade fans</li>\n<li>Core clock, OC mode: 1582 MHz base / 1797 MHz boost</li>\n<li>Core clock, Gaming mode: 1556 MHz base / 1771 MHz boost</li>\n<li>Power design: 4+1 phases</li>\n</ul><h3>Compatibility and gaming</h3><p>The GTX 1060 3GB is suited to many older and esports titles at 1080p; frame rates and settings depend on the game and system. Check case clearance, PSU requirements and display outputs against the actual card before purchasing.</p><h3>Frequently asked questions</h3><h4>Is this graphics card new?</h4><p>No. This listing is described as used and without box.</p><h4>How much VRAM does it have?</h4><p>3GB GDDR5 memory with a 192-bit interface.</p><h4>Is it suitable for every gaming PC?</h4><p>No. Confirm motherboard slot, power supply, case clearance and monitor connections before ordering.</p>','\n',char(10)),26000,NULL,1,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/2000_2048x2048_94bf209a-918b-4902-af70-a605002c14b6.webp?v=1727942505','https://sakoonsay.com/products/gigabyte-graphic-card-gtx-1060-3gb-windforce-gddr5-without-box-used.js','Graphics Cards',1,'normal',20,'used,refurbi