INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(4015,'15404611567669','msi-mag-a750gl-pcie5-750w-80-plus-gold-fully-modular-power-supply','MSI MAG A750GL PCIE5 750W 80 PLUS Gold Fully Modular Power Supply',replace('<h2>MSI MAG A750GL PCIE5 750W 80 PLUS Gold Fully Modular PSU</h2><p>MSI MAG A750GL PCIE5 750W gaming power supply with 80 PLUS Gold efficiency, fully modular flat cables, native 16-pin PCIe graphics card power connection rated up to 450W, 120mm fluid dynamic bearing fan and active PFC. <strong>Important revision note:</strong> MSI published both ATX 3.0 / PCIe 5.0 and later ATX 3.1 / PCIe 5.1 documentation for the MAG A750GL PCIE5. The physical unit''s revision must be verified before promising ATX 3.1 or PCIe 5.1. This is not the separate MAG A750GL PCIE5 II model.</p><h3>Manufacturer specifications</h3><ul>\n<li>Rated power: 750W</li>\n<li>80 PLUS Gold efficiency, up to 90%</li>\n<li>Fully modular flat cables</li>\n<li>Native PCIe 16-pin graphics connector ×1 (450W)</li>\n<li>PCIe 6+2-pin ×3; EPS 4+4-pin ×2; ATX 24-pin ×1</li>\n<li>SATA ×8; peripheral 4-pin ×4; FDD ×1</li>\n<li>120mm fluid dynamic bearing fan</li>\n<li>Dimensions: 140 × 150 × 86mm</li>\n<li>Input: 100–240V AC, 47–63Hz</li>\n<li>Protections: OCP, OVP, OPP, OTP, SCP, UVP</li>\n</ul><p><strong>Availability:</strong> Out of stock.</p><p><strong>Warranty:</strong> Local SakoonSay/distributor warranty duration has not been verified; please contact the store for applicable warranty terms. No unverified local warranty duration is promised.</p><p><a href="https://www.msi.com/Power-Supply/MAG-A750GL-PCIE5/Specification">Official MSI specifications</a>.</p>','\n',char(10)),27999,NULL,0,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/msi-mag-a750gl-pcie5-product_75d312a7-58f2-4709-87d7-cbf06f7c43db.webp?v=17914997