INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(4016,'15404611403829','deepcool-pn750m-750w-80-plus-gold-fully-modular-atx-3-1-psu','DeepCool PN750M 750W 80 PLUS Gold Fully Modular ATX 3.1 PSU',replace('<h2>DeepCool PN750M 750W Gold Fully Modular ATX 3.1 PSU</h2><p>Genuine black DeepCool PN750M power supply. Designed for ATX 3.1 and PCIe 5.1 gaming PCs, with fully modular sleeved cables and a native 12V-2x6 cable rated for up to 450W graphics card power. This is PN750M, not the non-modular PN750D or white PN750M WH.</p><h3>Official DeepCool specifications</h3><ul>\n<li>750W continuous rated output, 80 PLUS Gold efficiency</li>\n<li>Intel ATX12V 3.1 and PCIe 5.1 compatible</li>\n<li>Fully modular cabling, native 12V-2x6 16-pin GPU connector (450W)</li>\n<li>120mm fluid dynamic bearing (FDB) fan</li>\n<li>Japanese bulk capacitor; active PFC, full bridge SRC LLC, DC-to-DC design</li>\n<li>Dimensions: 150 × 140 × 86 mm (W × L × H)</li>\n<li>Efficiency at typical 50% load: ≥90%</li>\n<li>Protection: OPP, OVP, SCP, OTP, OCP, UVP, SIP, NLO</li>\n<li>Operating temperature: 0–40°C</li>\n</ul><p><strong>Manufacturer part-number family:</strong> R-PN750M-FC0B. Region-specific suffixes (UK, EU, WO and others) differ; confirm the exact suffix on the supplied retail box before dispatch.</p><p><strong>Warranty:</strong> DeepCool advertises a 10-year limited manufacturer warranty subject to manufacturer terms and regional eligibility. SakoonSay local seller/distributor warranty duration has not been confirmed and is not promised.</p><p>Official manufacturer specifications: <a href="https://global.deepcool.com/products/PowerSupplyUnits/powersupplyunits/PN750M-ATX3.1-Modular-Power-Supply/2023/17877.shtml">DeepCool PN750M</a>.</p>','\n',char(10)),27499,NULL,0,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/deepcool-pn750m-750w-gold.webp?v=1791499603','https://sakoonsay.com/products/deepcool-pn750m-750w-80-plus-gold-fully-modular-atx-3-1-psu.js','Power Supply',1,'normal',20,'used,refurbished,new','2026-10-22 08:03:14');
