INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(4018,'15404610748469','corsair-rm750e-750w-80-plus-gold-fully-modular-atx-3-1-power-supply','Corsair RM750e 750W 80 PLUS Gold Fully Modular ATX 3.1 Power Supply',replace('<h2>Corsair RMe Series RM750e 750W 80 PLUS Gold Fully Modular PSU</h2><p>Premium, compact 750W power supply with fully modular Type 4 cabling, 80 PLUS Gold efficiency, ATX 3.1 certification and PCIe 5.1 compatibility. This listing describes Corsair RM750e part-number family <strong>CP-9020262</strong>, including the official WW model <strong>CP-9020262-WW</strong>. Regional plug suffix must be verified against the physical box before dispatch; do not substitute the different CP-9020295 revision without confirming specifications.</p><h3>Official specifications for CP-9020262 series</h3><ul>\n<li>Continuous output: 750W; +12V rail 62.5A</li>\n<li>80 PLUS Gold efficiency</li>\n<li>Fully modular Corsair Type 4 cables</li>\n<li>ATX 3.1, PCIe 5.1 compliant</li>\n<li>Native 12V-2x6 12+4-pin GPU cable</li>\n<li>Zero RPM fan mode for quiet low-load operation</li>\n<li>Dimensions: 140 × 150 × 86mm</li>\n<li>Input: 100–240V, 47–63Hz</li>\n<li>Connectors: ATX 24-pin ×1; EPS 4+4-pin ×2; PCIe 6+2-pin ×3; 12V-2x6 ×1; SATA ×7; PATA ×4</li>\n<li>105°C-rated capacitors, LLC resonant topology and DC-to-DC conversion</li>\n</ul><p><strong>Availability:</strong> Out of stock (0 units).</p><p><strong>Warranty:</strong> Corsair states a seven-year limited manufacturer warranty for this model, subject to regional eligibility and manufacturer terms. No local SakoonSay/distributor warranty duration has been verified or promised; contact the store for applicable local terms.</p><p>Manufacturer reference: <a href="https://www.corsair.com/ww/en/p/psu/cp-9020262-ww/rme-series-rm750e-fully-modular-low-noise-atx-power-supply-cp-9020262-ww">Corsair RM750e CP-9020262-WW</a>.</p>','\n',char(10)),32999,NULL,0,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/corsair-rm750e-cp-9020262-750w_f70abd2b-c64d-4cd7-ba39-75b474632fbe.jpg?v=1791499394','https://sakoonsay.com/products/corsair-rm750e-750w-80-plus-gold-fully-modular-atx-3-1-power-supply.js','Power Supply',1,'normal',20,'used,refurbished,new','2026-10-22 08:03:14');
