INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(4024,'15404609667125','corsair-cx650-650w-80-plus-bronze-atx-power-supply-non-modular','Corsair CX650 650W 80 PLUS Bronze ATX Power Supply – Non-Modular',replace('<h2>Corsair CX650 650W 80 PLUS Bronze Power Supply in Pakistan</h2><p>The Corsair CX Series CX650 delivers 650W of continuous power for compatible gaming and productivity PCs. This is the <strong>non-modular CX650 (CP-9020278 series)</strong>, not the CX650M or older CP-9020122 revision.</p><h3>Official Features &amp; Specifications</h3><ul>\n<li>Continuous output: 650 watts</li>\n<li>80 PLUS Bronze certified efficiency, up to 88%</li>\n<li>120mm thermally controlled, low-noise sleeve-bearing fan</li>\n<li>ATX12V v2.31, non-modular fixed cables</li>\n<li>Compact 125mm length</li>\n<li>Connectors: 1 × ATX 24-pin; 1 × EPS/CPU 4+4-pin; 2 × PCIe 6+2-pin; 3 × SATA; 2 × PATA/Molex</li>\n<li>Universal AC input: 100–240V, 47–63Hz</li>\n</ul><p><strong>Warranty information:</strong> Corsair lists a 5-year manufacturer limited warranty for qualifying CX650 units, subject to manufacturer conditions and regional eligibility. SakoonSay''s own local warranty coverage has not been confirmed; please contact us for applicable terms.</p><p><strong>Availability:</strong> Currently out of stock. Contact SakoonSay Gaming Store for restock information.</p><p>Official specifications: <a href="https://www.corsair.com/ww/en/p/psu/cp-9020278-ww/cx-series-cx650-650-watt-80-plus-bronze-atx-power-supply-ww-cp-9020278-ww">Corsair CX650 CP-9020278</a>.</p>','\n',char(10)),17499,NULL,0,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/corsair-cx650-650w-non-modular-front_af1fee9c-5762-4952-8638-4fe81e92d0ee.png?v=1791498726','https://sakoonsay.com/products/corsair-cx650-650w-80-plus-bronze-atx-power-supply-n