INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(14889,'15414710075445','gigabyte-h81m-ds2v-4th-gen-lga1150-micro-atx-motherboard-ddr3','GIGABYTE H81M-DS2V 4th Gen LGA1150 Micro-ATX Motherboard – DDR3',replace('<p><strong>GIGABYTE GA-H81M-DS2V Micro-ATX Motherboard</strong> for affordable Intel 4th Generation desktop upgrades and budget PC builds.</p>\n<h2>Specifications</h2>\n<ul>\n<li>\n<strong>Socket:</strong> LGA1150 for compatible Intel 4th Gen Core i7, i5, i3, Pentium and Celeron processors</li>\n<li>\n<strong>Chipset:</strong> Intel H81 Express</li>\n<li>\n<strong>Memory:</strong> 2× DDR3 DIMM slots, dual-channel, up to 16GB; DDR3 1600/1333MHz support</li>\n<li>\n<strong>Expansion:</strong> 1× PCI Express 2.0 x16 and 2× PCI Express 2.0 x1 slots</li>\n<li>\n<strong>Display outputs:</strong> DVI-D and D-Sub; integrated graphics depend on the installed CPU</li>\n<li>\n<strong>Storage:</strong> 2× SATA 6Gb/s and 2× SATA 3Gb/s connectors</li>\n<li>\n<strong>USB:</strong> USB 3.0 and USB 2.0 connectivity</li>\n<li>\n<strong>Network:</strong> Realtek Gigabit LAN</li>\n<li>\n<strong>Audio:</strong> Realtek high-definition audio</li>\n<li>\n<strong>Design:</strong> GIGABYTE Ultra Durable technology, UEFI BIOS and all-solid capacitors</li>\n<li>\n<strong>Form factor:</strong> Micro-ATX</li>\n</ul>\n<h2>Compatibility note</h2>\n<p>Confirm the LGA1150 socket and DDR3 memory requirement before ordering. A compatible Intel CPU, RAM, storage, power supply and case are required to build a complete PC.</p>\n<h2>Frequently asked questions</h2>\n<h3>Which processors are compatible?</h3>\n<p>This board supports compatible Intel 4th Gen Core i7, i5 and i3 processors, plus Pentium and Celeron CPUs using the LGA1150 socket.</p>\n<h3>How much RAM can it support?</h3>\n<p>It supports up to 16GB of DDR3 memory across two DIMM slots in dual-channel mode.</p>\n<h3>Can I install a graphics card?</h3>\n<p>Yes. It includes a PCIe 2.0 x16 slot for a compatible dedicated graphics card.</p>\n<h3>Is this a complete PC?</h3>\n<p>No. This listing is for the motherboard only. CPU, RAM, storage, power supply and case are not included unless specifically stated.</p>','\n',char(10)),4500,NULL,1,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/gigabyte-ga-h81m-ds2v-micro-atx-motherboard.png?v=1792163031','https://sakoonsay.com/products/gigabyte-h81m-ds2v-4th-gen-lga1150-micro-atx-motherboard-ddr3.js','Motherboard',1,'normal',20,'used,refurbished,new','2026-10-22 08:02:31');
INSERT INTO "products" ("id","source_id","handle","title","description","price_pkr","compare_at_pkr","available","image_url","source_url","category","sourcing_enabled","priority","min_margin_pct","condition_rule","updated_at") VALUES(14890,'15414709944373','asrock-h81m-hds-4th-gen-lga1150-micro-atx-motherboard-ddr3','ASRock H81M-HDS 4th Gen LGA1150 Micro-ATX Motherboard – DDR3',replace('<p><strong>ASRock H81M-HDS Micro-ATX Motherboard</strong> for Intel 4th Generation desktop computers, budget upgrades and entry-level gaming PC builds.</p>\n<h2>Specifications</h2>\n<ul>\n<li>\n<strong>Socket:</strong> LGA1150 for compatible 4th Gen Intel Core i7, i5, i3, Xeon, Pentium and Celeron processors</li>\n<li>\n<strong>Chipset:</strong> Intel H81</li>\n<li>\n<strong>Memory:</strong> 2× DDR3/DDR3L DIMM slots, dual-channel, up to 16GB; 1600/1333/1066MHz support</li>\n<li>\n<strong>Expansion:</strong> 1× PCIe 2.0 x16 and 1× PCIe 2.0 x1</li>\n<li>\n<strong>Display outputs:</strong> HDMI, DVI-D and D-Sub; display support depends on the installed CPU</li>\n<li>\n<strong>Storage:</strong> 2× SATA 6Gb/s and 2× SATA 3Gb/s</li>\n<li>\n<strong>USB:</strong> USB 3.1 Gen1 and USB 2.0 connectivity</li>\n<li>\n<strong>Network:</strong> Realtek Gigabit LAN</li>\n<li>\n<strong>Audio:</strong> 5.1-channel HD audio with Realtek ALC662 codec</li>\n<li>\n<strong>Form factor:</strong> Micro-ATX</li>\n</ul>\n<h2>Why choose this motherboard?</h2>\n<p>The ASRock H81M-HDS is a practical platform for an affordable LGA1150 computer. Pair it with compatible DDR3 memory, a 4th Gen Intel processor, storage, power supply and case for an everyday PC or budget gaming build.</p>\n<h2>Frequently asked questions</h2>\n<h3>Which processors are compatible?</h3>\n<p>It supports compatible Intel 4th Gen Core i7, i5 and i3 processors, as well as Xeon, Pentium and Celeron CPUs using the LGA1150 socket.</p>\n<h3>How much RAM does it support?</h3>\n<p>It supports up to 16GB of DDR3 or DDR3L memory across two DIMM slots in dual-channel mode.</p>\n<h3>Can I use a graphics card?</h3>\n<p>Yes. It includes a PCIe 2.0 x16 slot for a compatible dedicated graphics card.</p>\n<h3>Is this a full PC?</h3>\n<p>No. This listing is for the motherboard only. CPU, RAM, storage, power supply and case are not included unless specifically stated.</p>','\n',char(10)),4500,NULL,1,'//cdn.shopify.com/s/files/1/0647/5196/0117/files/asrock-h81m-hds-micro-atx-motherboard.png?v=1792162857','https://sakoonsay.com/products/asrock-h81m-hds-4th-gen-lga1150-micro-atx-motherboard-ddr3.js','Motherboard',1,'normal',20,'used,refurbished,new','2026-10-22 08:02:31');
