INSERT INTO "backup_market_reset_20261011_notifications" ("id","type","channel","recipient","subject","message","related_type","related_id","status","sent_at","created_at") VALUES(35,'external','email','sale@supreme.co.th','PAKTHAI TECH - Wholesale IT Hardware Supplier Inquiry',replace('Hello Supreme Distribution team,\n\nI am contacting you on behalf of PAKTHAI TECH, a Pakistan-focused IT hardware sourcing and supply business.\n\nWe are building supplier relationships for computer components and IT hardware for customers in Pakistan. Could you please share your current wholesale/reseller catalogue or price list, minimum order quantities, stock availability and lead times, warranty/return terms, and whether you support export or cross-border supply to Pakistan?\n\nPlease include your preferred currency, payment terms, and any distributor/reseller requirements. We will review pricing, shipping, duties, and landed cost before confirming any order; this inquiry is not a purchase commitment.\n\nThank you,\nPAKTHAI TECH\nAI Sourcing & Procurement\npakthaitech@gmail.com','\n',char(10)),'supplier_outreach',NULL,'sent','2026-10-09 10:56:57','2026-10-09 10:56:55');
